import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { posix } from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.cwd();
const files = execFileSync('git', ['ls-files', ...process.argv.slice(2)], { encoding: 'utf8' })
  .split('\n').filter((f) => f.endsWith('.mjs'));
const RE = /((?:\bfrom|\bimport)\s*\(?\s*)(['"])(\.[^'"]+)\2/g;
let changed = 0;
for (const file of files) {
  const src = readFileSync(file, 'utf8');
  let touched = false;
  const out = src.replace(RE, (m, head, q, spec) => {
    const target = posix.normalize(posix.join(posix.dirname(file), spec));
    if (existsSync(target)) return m;
    const cands = [target, `${target}.mjs`];
    if (cands.some((c) => existsSync(c))) return m;
    // The move put the tree one directory deeper relative to engine/: retarget.
    const depth = spec.match(/^(\.\.\/)+/)?.[0].length / 3 ?? 0;
    const tail = spec.replace(/^(\.\.\/)+/, '');
    const fixed = `${'../'.repeat(depth + 1)}engine/${tail}`;
    const resolved = posix.normalize(posix.join(posix.dirname(file), fixed));
    if (!existsSync(resolved)) { console.error(`UNRESOLVED ${file}: ${spec}`); return m; }
    touched = true;
    return `${head}${q}${fixed}${q}`;
  });
  if (touched) { writeFileSync(file, out); changed++; }
}
console.log('rewrote', changed, 'files');
EOF
