            fix: 'move the script into a module under packs/claudinite-tasks/queue/ and call it with a single-line `run: node <module>`; the engine converges nightly, this file needs a human-merged PR per repo',
          }));
        }
      });
    }
    return out;
  },
};

export default rule;

