import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { posix } from 'node:path';
import { execFileSync } from 'node:child_process';

const MOVED = 'packs/claudinite-lifecycle/updates/';
const OLD = 'updates/';
const oldOf = (f) => (f.startsWith(MOVED) ? OLD + f.slice(MOVED.length) : f);
const newOf = (t) => (t.startsWith(OLD) ? MOVED + t.slice(OLD.length) : t);
const has = (p) => existsSync(p) || existsSync(`${p}.mjs`);
const files = execFileSync('git', ['ls-files'], { encoding: 'utf8' }).split('\n').filter((f) => f.endsWith('.mjs'));
const RE = /((?:\bfrom|\bimport)\s*\(?\s*)(['"])(\.[^'"]+)\2/g;
let changed = 0; const bad = [];
for (const file of files) {
  const src = readFileSync(file, 'utf8');
  let touched = false;
  const out = src.replace(RE, (m, head, q, spec) => {
    if (has(posix.normalize(posix.join(posix.dirname(file), spec)))) return m;
    const target = newOf(posix.normalize(posix.join(posix.dirname(oldOf(file)), spec)));
    if (!has(target)) { bad.push(`${file}: ${spec} -> ${target}`); return m; }
    let rel = posix.relative(posix.dirname(file), target);
    if (!rel.startsWith('.')) rel = `./${rel}`;
    touched = true; return `${head}${q}${rel}${q}`;
  });
  if (touched) { writeFileSync(file, out); changed++; }
}
console.log('rewrote', changed);
if (bad.length) console.error('UNRESOLVED:\n' + bad.join('\n'));
EOF
